typedef struct {
    float x, y;       // position
    float vx, vy;     // velocity
} Particle;

static Particle particles[1000];

static void integrate(Particle *ps, int n, float dt) {
    const float G = 9.8f;          // gravity, m/s^2
    for (int i = 0; i < n; i++) {
        ps[i].vy -= G * dt;          // 1. update velocity first
        ps[i].x  += ps[i].vx * dt;   // 2. then position uses new vy
        ps[i].y  += ps[i].vy * dt;
    }
}

