typedef struct { char *base; size_t cap; size_t off; } Arena;

static void *arena_alloc(Arena *a, size_t bytes) {
    /* 1. Round up current offset to 8-byte boundary for alignment */
    size_t aligned = (a->off + 7u) & ~(size_t)7u;
    /* 2. Out of memory? */
    if (aligned + bytes > a->cap) return NULL;
    /* 3. Hand out the pointer and advance */
    void *p = a->base + aligned;
    a->off = aligned + bytes;
    return p;
}

static void arena_reset(Arena *a) { a->off = 0; }

