typedef struct { float w, x, y, z; } quat;

static quat quat_normalize(quat q) {
    float len = sqrtf(q.w*q.w + q.x*q.x + q.y*q.y + q.z*q.z);
    if (len < 1e-6f) return (quat){1, 0, 0, 0};
    return (quat){q.w/len, q.x/len, q.y/len, q.z/len};
}

static quat quat_slerp(quat a, quat b, float t) {
    a = quat_normalize(a); b = quat_normalize(b);
    float dot = a.w*b.w + a.x*b.x + a.y*b.y + a.z*b.z;
    if (dot < 0) { b.w = -b.w; b.x = -b.x; b.y = -b.y; b.z = -b.z; dot = -dot; }
    if (dot > 0.9995f) {   /* nearly parallel: plain lerp + normalize, avoid sin(0) divide */
        quat q = {a.w + (b.w-a.w)*t, a.x + (b.x-a.x)*t,
                  a.y + (b.y-a.y)*t, a.z + (b.z-a.z)*t};
        return quat_normalize(q);
    }
    float th = acosf(dot), s = sinf(th);
    float w1 = sinf((1-t)*th)/s, w2 = sinf(t*th)/s;
    return (quat){a.w*w1 + b.w*w2, a.x*w1 + b.x*w2,
                  a.y*w1 + b.y*w2, a.z*w1 + b.z*w2};
}

