typedef struct { float prio[128]; int val[128]; int len; } MinHeap;

static void swap(MinHeap *h, int a, int b) {
    float tp = h->prio[a]; h->prio[a] = h->prio[b]; h->prio[b] = tp;
    int   tv = h->val[a];  h->val[a]  = h->val[b];  h->val[b]  = tv;
}

static void heap_push(MinHeap *h, float prio, int val) {
    int i = h->len++;
    h->prio[i] = prio;
    h->val[i]  = val;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (h->prio[p] <= h->prio[i]) break;
        swap(h, i, p);
        i = p;
    }
}

