typedef struct { int n; const int *offsets; const int *nbrs; } Graph;

static int bfs_dist(const Graph *g, int start, int target) {
    if (start == target) return 0;
    if (start < 0 || start >= g->n) return -1;

    char *seen = calloc((size_t)g->n, 1);
    int  *dist = malloc((size_t)g->n * sizeof(int));
    int  *q    = malloc((size_t)g->n * sizeof(int));
    if (!seen || !dist || !q) { free(seen); free(dist); free(q); return -1; }

    int head = 0, tail = 0;
    seen[start] = 1; dist[start] = 0;
    q[tail++] = start;
    while (head < tail) {
        int u = q[head++];
        for (int k = g->offsets[u]; k < g->offsets[u+1]; k++) {
            int v = g->nbrs[k];
            if (seen[v]) continue;
            seen[v] = 1;
            dist[v] = dist[u] + 1;
            if (v == target) { free(seen); free(dist); free(q); return dist[v]; }
            q[tail++] = v;
        }
    }
    free(seen); free(dist); free(q);
    return -1;
}

