static void verlet_step(Ball *b, int i) {
    /* acceleration at the current position */
    float dx = b->x - CX, dy = b->y - CY;
    float ax = -K[i] * dx, ay = -K[i] * dy;

    /* drift: half a kick worth of acceleration rides in the position step */
    b->x += b->vx * DT + 0.5f * ax * DT * DT;
    b->y += b->vy * DT + 0.5f * ay * DT * DT;

    /* acceleration at the NEW position */
    dx = b->x - CX; dy = b->y - CY;
    float ax2 = -K[i] * dx, ay2 = -K[i] * dy;

    /* kick: average old and new acceleration */
    b->vx += 0.5f * (ax + ax2) * DT;
    b->vy += 0.5f * (ay + ay2) * DT;
}

